def draw_board(c,cx,cy,scale=1,labels=True,traces=False):
    c.saveState();c.translate(cx*mm,cy*mm);c.scale(scale*mm,scale*mm);c.setLineWidth(.08);c.setStrokeColor(INK);c.circle(0,0,22)
    if traces:
        c.setStrokeColorRGB(.67,.37,.12)
        for t in G['tracks']:c.setLineWidth(t['width']);c.line(t['a'][0],-t['a'][1],t['b'][0],-t['b'][1])
    for ref,d in C.items():
        x,y=d['x'],-d['y'];c.setLineWidth(.1);c.setStrokeColor(INK);c.setFillColorRGB(.92,.95,.97)
        if ref.startswith('SW'):
            c.rect(x-2.4,y-2.4,4.8,4.8,stroke=1,fill=1);c.circle(x,y,1.5,stroke=1,fill=0)
            if labels:c.setFont('ArialBold',1.1);c.drawCentredString(x,y+3.2,ref)
        elif ref.startswith('H'):
            c.circle(x,y,1.1);c.setDash(.4,.4);c.circle(x,y,2.5);c.setDash()
            c.line(x-.7,y,x+.7,y);c.line(x,y-.7,x,y+.7)
        elif ref.startswith(('R','C')):
            rot=math.radians(d['rot']);ww,hh=(.8,1.6) if d['rot']%180 else (1.6,.8)
            c.rect(x-ww/2,y-hh/2,ww,hh,stroke=1,fill=1)
        for dpad in d['pads']:
            if dpad['npth']:continue
            px,py=dpad['x'],-dpad['y'];c.setFillColorRGB(.91,.74,.25);c.setLineWidth(.04)
            if dpad['drill']>0:
                c.circle(px,py,dpad['w']/2,stroke=1,fill=1);c.setFillColorRGB(1,1,1);c.circle(px,py,dpad['drill']/2,stroke=1,fill=1)
            else:
                w,h=dpad['w'],dpad['h']
                if dpad['rotation']%180:w,h=h,w
                c.rect(px-w/2,py-h/2,w,h,stroke=1,fill=1)
    c.setStrokeColorRGB(.3,.5,.65);c.setDash(.6,.5);c.setLineWidth(.07);c.circle(0,0,7.5)
    for x,y in [(-8,-8),(8,-8),(-10,10),(10,10)]:c.circle(x,-y,1.15)
    c.setDash();c.restoreState()

